function sum(values) { return values.reduce((a, b) => a + b, 0); }
function mean(values) {
  if (!Array.isArray(values) || !values.every((v) => typeof v === 'number' && Number.isFinite(v))) {
    throw new TypeError('mean expects an array of finite numbers');
  }
  return values.length === 0 ? null : sum(values) / values.length;
}
module.exports = { sum, mean };

const test=require('node:test'); const assert=require('node:assert/strict'); const {sum,mean}=require('../src/stats.cjs');
test('sum',()=>assert.equal(sum([1,2,3]),6));
test('sum of empty array is 0',()=>assert.equal(sum([]),0));
test('mean of empty array is null',()=>assert.equal(mean([]),null));
test('mean returns arithmetic mean',()=>{
  assert.equal(mean([1,2,3,4]),2.5);
  assert.equal(mean([5]),5);
  assert.equal(mean([-2,2,-4]),-4/3);
});
test('mean does not mutate input',()=>{
  const values=[3,1,2]; const frozen=Object.freeze([3,1,2]);
  assert.equal(mean(values),2); assert.deepEqual(values,[3,1,2]);
  assert.equal(mean(frozen),2);
});
test('mean rejects non-arrays with TypeError',()=>{
  for (const bad of [undefined,null,1,'123',{length:1,0:1},new Set([1])]) assert.throws(()=>mean(bad),TypeError);
});
test('mean rejects non-finite or non-number elements with TypeError',()=>{
  for (const bad of [[1,NaN],[Infinity],[-Infinity,1],['1'],[1,null],[undefined],[1n],[new Number(1)],[1,,3]]) assert.throws(()=>mean(bad),TypeError);
});

